"""Choose a reasonable DMstep by setting the maximum smearing across the
        'BW' to equal the sampling time 'dt'.

        Inputs:
            dt: sampling time (in seconds)
            BW: bandwidth (in MHz)
            fctr: centre frequency (in MHz)
    """
def guess_DMstep(dt: Any, BW: Any, fctr: Any) -> object {
    return ((dt * 0.0001205 * (fctr ** 3.0)) / BW);
}

"""
    Function to cut the passed in string before \n\n if any

    Parameters
    ----------
    description: str
        the passed in string for process

    Returns
    -------
    str
        processed string
    """
def process_description(description: str) -> object {
    if not description {
        return "No Info Provided";
    }
    return description.rpartition('\n\n')[0]
        if ("\n\n" in description)
        else description;
}

"""Checks if the path argument is a Windows platform path."""
def is_windows_path(path: Any) -> object {
    return (('\\' in path) or (':' in path) or ('|' in path));
}

""" compute cross-product of args """
def cross(*args: list[str]) -> list[str] {
    return [arg + arg2 for arg in args[0] for arg2 in args[1]];
}

"""
    Pads the base64 string.
    """
def pad_base64_str(str: Any) -> object {
    missing_padding = len(str) % 4;
    if (missing_padding != 0) {
        str += '=' * (4 - missing_padding);
    }
    return str;
}

"""Return number of bytes as string with most appropriate unit."""
def human_size(`bytes: Any) -> object {
    if (`bytes == 0) {
        return '0 B';
    }
    suffixes = ['B', 'KB', 'MB', 'GB', 'TB', 'PB', 'YB'];
    `bytes = float(`bytes);
    i = 0;
    while ((`bytes >= 1024) and (i < (len(suffixes) - 1))) {
        `bytes /= 1024.0;
        i += 1;
    }
    if (i > 2) {
        f = '{:0.2f}'.format(`bytes);
    } else {
        f = '{:0.1f}'.format(`bytes);
    }
    f = f.rstrip('0').rstrip('.');
    return '{} {}'.format(f, suffixes[i]);
}

"""
    Get image type.

    :param fileName:
    :return:
    """
def get_image_type(fileName: Any) -> object {
    if fileName.endswith(".jpg") {
        return "image/jpeg";
    } elif fileName.endswith(".png") {
        return "image/png";
    }
}
